    nblo=set(noise_cols(di,R+h,H,C,w))
    for i in range(0,R):
        paint(i,nrange(C,C+w)-nbove)
    for i in range(R+h,H):
        paint(i,nrange(C,C+w)-nblo)
    for i in range(R,R+h):
        rights=any(di[i][j]!=0 and di[i][j]!=2 and j>C+w-1 for j in range(W))
        lefts=any(di[i][j]!=0 and di[i][j]!=2 and j<C for j in range(W))
        target = range(0,C+w) if rights else (range(C,W) if lefts else range(0,W))
        for j in target:
            out[i][j]=2
    return out
def noise_cols(di,b1,b2,C,w):
    s=set()
    for i in range(b1,b2+1):
        for j in range(C,C+w):
            if di[i][j] not in (0,2): s.add(j)
    return s
def nrange(a,b,s):
    return set(range(a,b+1))-s
