    R=min(i for i,_ in pts); C=min(j for _,j in pts)
    h=max(i for i,_ in pts)-R+1; w=max(j for _,j in pts)-C+1
    out=[r[:] for r in di]
    def band_noise(rows):
        s=set()
        for i in rows:
            for j in range(C,C+w):
                if di[i][j] not in (0,2): s.add(j)
        return s
    nbv=band_noise(range(0,R))      # above block rows
    nbl=band_noise(range(R+h,H))    # below block rows
    def paint(row,j):
        if 0<=row<H and 0<=j<W: out[row][j]=2
    for i in range(0,R):
        for j in range(C,C+w):
            if j not in nbv: paint(i,j)
    for i in range(R+h,H):
        for j in range(C,C+w):
            if j not in nbl: paint(i,j)
    for i in range(R,R+h):
        rights=any(di[i][j]!=0 and di[i][j]!=2 and j>C+w-1 for j in range(W))
        lefts=any(di[i][j]!=0 and di[i][j]!=2 and j<C for j in range(W))
        if rights: 
            for j in range(0,C+w): out[i][j]=2
        elif lefts:
            for j in range(C,W): out[i][j]=2
        else:
            for j in range(W): out[i][j]=2
    return out
